package com.syfe.finance.controller;
import com.syfe.finance.dto.Requests; import com.syfe.finance.service.FinanceService; import jakarta.servlet.http.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.authentication.*; import org.springframework.security.core.Authentication; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.context.HttpSessionSecurityContextRepository; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final FinanceService service; private final AuthenticationManager authManager;
 public AuthController(FinanceService s,AuthenticationManager a){service=s;authManager=a;}
 @PostMapping("/register") ResponseEntity<Map<String,Object>> register(@Valid @RequestBody Requests.Register r){return ResponseEntity.status(201).body(service.register(r));}
 @PostMapping("/login") ResponseEntity<Map<String,String>> login(@Valid @RequestBody Requests.Login r,HttpServletRequest request){try{Authentication auth=authManager.authenticate(new UsernamePasswordAuthenticationToken(r.username().trim().toLowerCase(java.util.Locale.ROOT),r.password()));SecurityContextHolder.getContext().setAuthentication(auth);request.getSession(true).setAttribute(HttpSessionSecurityContextRepository.SPRING_SECURITY_CONTEXT_KEY,SecurityContextHolder.getContext());return ResponseEntity.ok(Map.of("message","Login successful"));}catch(BadCredentialsException e){throw new com.syfe.finance.exception.ApiException(HttpStatus.UNAUTHORIZED,"Invalid username or password");}}
 @PostMapping("/logout") ResponseEntity<Map<String,String>> logout(HttpServletRequest request,HttpServletResponse response){var session=request.getSession(false);if(session==null)throw new com.syfe.finance.exception.ApiException(HttpStatus.UNAUTHORIZED,"No active session");session.invalidate();SecurityContextHolder.clearContext();Cookie cookie=new Cookie("JSESSIONID","");cookie.setPath("/");cookie.setMaxAge(0);cookie.setHttpOnly(true);response.addCookie(cookie);return ResponseEntity.ok(Map.of("message","Logout successful"));}
}
